insert into public.units (id, owner_id, data) values
('e26c62b0-1f40-4637-8973-f51767cb35b1', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"subject": "Physique-Chimie", "level": "4e", "theme": "3", "id": "e26c62b0-1f40-4637-8973-f51767cb35b1", "kind": "sequence", "code": "434", "order": 5, "name": "Les lois des circuits électriques (v2)", "documents": [{"mediaId": "doc-55ea5f07-cb5a-4d51-91e2-176038bc6a8c", "name": "PC-4e-434-R Rôles de la table et aide multimètre.pdf", "size": 77166}, {"mediaId": "doc-57d69eb6-af32-4271-ba0e-7c2490f52348", "name": "Circuit interactif (série et dérivation).html", "size": 13467}], "description": "**Version 2** de la séquence 432 (démarche d''investigation, 3 séances + DS). Classe hétérogène (ULIS, PPRE, PPS) : chaque fiche existe en version standard et en version aménagée (A).\n**Objectifs** : comportement de l''intensité et de la tension en série et en dérivation ; **loi des nœuds** (ce qui arrive à un nœud en repart) et **loi des mailles** (dans une boucle, la tension du générateur se partage ; en dérivation, même tension) ; en fin de séquence seulement, les 4 lois habituelles comme conséquences ; maîtrise du multimètre (mode, branchement, COM, calibre, unité). Ouverture loi d''Ohm pour les avancés.\n**Organisation** : 7 tables de 3-4, rôles tournants (manipulateur → mesureur → secrétaire → porte-parole → gardien du temps), fiche de table à plastifier. Protocoles prévus avec 1 ou 2 multimètres par table. Carte mentale construite au fil des séances.\n**Matériel** : générateurs 6 V, lampes identiques, résistances, moteurs (option), fils, multimètres, cartes A/B/C/D ou Plickers, vidéoprojecteur.\n**Professeur** : le guide (idées fausses, diagnostic, déroulé, différenciation), le DS en 2 versions et le corrigé sont dans Évaluations, modèle « DS – Les lois des circuits électriques (v2) » (documents non visibles des élèves).\nSources LaTeX : cours-latex/Physique-Chimie/PC-4e-434 Lois des circuits (v2)."}'::jsonb),
('d98e16b5-1d8a-41cd-b5b3-06b82e5bd29c', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"subject": "Physique-Chimie", "level": "4e", "theme": "3", "id": "d98e16b5-1d8a-41cd-b5b3-06b82e5bd29c", "kind": "seance", "parentId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "code": "4341", "order": 1, "duration": 1, "name": "Le circuit en série (diagnostic + TP)", "documents": [{"mediaId": "doc-da494083-8fbd-4536-b1b9-1caaffebf430", "name": "PC-4e-434-S1 Le circuit en série - fiche élève.pdf", "size": 87755}, {"mediaId": "doc-0f97a897-279d-4a16-94b3-e7e55a81c806", "name": "PC-4e-434-S1A Le circuit en série - fiche élève aménagée.pdf", "size": 92630}], "description": "**Diagnostic** (10 min, cartes A/B/C/D, 5 questions : unité de I, branchement de l''ampèremètre, photo d''un voltmètre, borne COM, lecture 4.5 sur calibre 20 V). Question réussie par moins de 2/3 → démonstration de 2 min ; élèves avec 2 erreurs ou plus → fiche aide multimètre, passage prioritaire.\n**Énigme de Léo** (5 min) : « la première lampe brille plus, après il reste moins de courant ». Hypothèses par table (5 min).\n**Mesures de I** aux points 1, 2, 3 (15 min ; 1 multimètre : on déplace l''appareil ; 2 multimètres : points 1 et 3 en même temps), inversion de L1 et L2. **Mesures de U** : UG, UL1, UL2 (10 min).\n**Mise en commun** (7 min) : I la même partout, le courant ne s''use pas ; UG = U1 + U2. **Défi détective** (3 min) : B est faux.\n**Carte mentale** : branches 1 (Mesurer) et 2 (Série). **Devoir** : en fin de fiche."}'::jsonb),
('04acb485-ccf8-4c45-9209-24b226f7b645', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"subject": "Physique-Chimie", "level": "4e", "theme": "3", "id": "04acb485-ccf8-4c45-9209-24b226f7b645", "kind": "seance", "parentId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "code": "4342", "order": 2, "duration": 1, "name": "Le circuit avec dérivation (TP)", "documents": [{"mediaId": "doc-fb0a27cd-7ae7-463c-9876-d7fbb513673c", "name": "PC-4e-434-S2 Le circuit avec dérivation - fiche élève.pdf", "size": 93358}, {"mediaId": "doc-cb7470c8-781a-4848-9e9d-e3e9e9ea9551", "name": "PC-4e-434-S2A Le circuit avec dérivation - fiche élève aménagée.pdf", "size": 97276}], "description": "**Quiz flash** (5 min, 3 questions sur la séance 1). **Énigme de la maison** (5 min) : pourquoi les autres lampes restent allumées ? Hypothèses (5 min) : l''intensité du générateur change-t-elle ? la tension se partage-t-elle ?\n**Mesures de I** : I (branche principale), I1, I2, puis on dévisse L2 (15 min). **Mesures de U** : UG, UL1, UL2 (10 min).\n**Mise en commun des 7 tables** (10 min) : projeter le tableau, débattre de « 0,48 A et 0,47 A » → notion d''écart de mesure. **Circuit mystère** (5 min) : 0,60 A et 0,20 A → 3 lampes.\nAvancés : circuit mixte, ouverture loi d''Ohm (U ÷ I avec une résistance). **Carte mentale** : branches 3 (Dérivation) et 6 (Mesures)."}'::jsonb),
('d72eab70-b9f3-4b34-a19c-7733465d8b9a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"subject": "Physique-Chimie", "level": "4e", "theme": "3", "id": "d72eab70-b9f3-4b34-a19c-7733465d8b9a", "kind": "seance", "parentId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "code": "4343", "order": 3, "duration": 1, "name": "Deux lois pour tout expliquer", "documents": [{"mediaId": "doc-04312fc3-3792-4c55-bf5f-e7e9511c094c", "name": "PC-4e-434-S3 Deux lois pour tout expliquer - fiche élève.pdf", "size": 90146}, {"mediaId": "doc-194bd921-0fc8-49eb-b01f-45066244d472", "name": "PC-4e-434-S3A Deux lois pour tout expliquer - fiche élève aménagée.pdf", "size": 88423}, {"mediaId": "doc-b4d31a73-2f08-413f-ada5-ed8a1e9981da", "name": "PC-4e-434-M Carte mentale (complète + 2 niveaux à compléter).pdf", "size": 88498}, {"mediaId": "doc-57d69eb6-af32-4271-ba0e-7c2490f52348", "name": "Circuit interactif (série et dérivation).html", "size": 13467}], "description": "**Quiz projeté** (5 min). **Formulation** (10 min) : une phrase pour l''intensité, une pour la tension → loi des nœuds, loi des mailles (animation « Circuit interactif », mode Prévois !).\n**Images** (8 min), après les mesures et avec leurs limites : l''eau dans des tuyaux, la randonnée (tension = dénivelé), la chaîne de vélo.\n**Énigmes par table** (15 min, points et classement) ; PhET « Circuit Construction Kit : DC » pour vérifier. **Les 4 lois** (10 min) : unicité et additivité de l''intensité ← loi des nœuds ; additivité et égalité des tensions ← loi des mailles.\n**Carte mentale finale** (7 min) : branches 4 et 5 ; niveau 1 (trous + banque de mots) ou niveau 2 (titres seuls)."}'::jsonb),
('39cdf944-24aa-49ac-a012-443d7669df5b', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"subject": "Physique-Chimie", "level": "4e", "theme": "3", "id": "39cdf944-24aa-49ac-a012-443d7669df5b", "kind": "seance", "parentId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "code": "4344", "order": 4, "duration": 1, "isEval": true, "name": "DS – Lois des circuits", "description": "DS écrit de 55 min, version standard ou aménagée (tiers-temps). Sujets, corrigé et barème : Évaluations, modèle « DS – Les lois des circuits électriques (v2) »."}'::jsonb);
insert into public.cards (id, owner_id, data) values
('2cf1bc8c-3710-4bc1-80ad-6fa48e8ad1e3', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2cf1bc8c-3710-4bc1-80ad-6fa48e8ad1e3", "code": "43ER-049", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "unité"], "front": "Quelle est l''unité de l''**intensité** électrique ?", "back": "L''**ampère** (symbole A).", "createdAt": 1795015027480, "updatedAt": 1795015027480}'::jsonb),
('b5b7d032-49fd-44a3-9bef-8666619e8e95', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "b5b7d032-49fd-44a3-9bef-8666619e8e95", "code": "43ER-050", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "unité"], "front": "Quelle est l''unité de la **tension** électrique ?", "back": "Le **volt** (symbole V).", "createdAt": 1795015027481, "updatedAt": 1795015027481}'::jsonb),
('e700c319-0eb0-4a23-8541-5f4df7d8cee4', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e700c319-0eb0-4a23-8541-5f4df7d8cee4", "code": "43ER-051", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "multimètre"], "front": "Comment brancher un **ampèremètre** ?", "back": "**En série**, dans le circuit, comme une lampe de plus. Le courant entre par la borne A et sort par COM.", "createdAt": 1795015027482, "updatedAt": 1795015027482}'::jsonb),
('2687629f-da9e-42e7-853a-fec5d2e30c29', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "2687629f-da9e-42e7-853a-fec5d2e30c29", "code": "43ER-052", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "multimètre"], "front": "Comment brancher un **voltmètre** ?", "back": "**En dérivation**, aux deux bornes du dipôle, sans ouvrir le circuit. Borne V côté +, borne COM côté −.", "createdAt": 1795015027483, "updatedAt": 1795015027483}'::jsonb),
('dffd3f06-32e0-4bfe-a324-6df28641e188', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "dffd3f06-32e0-4bfe-a324-6df28641e188", "code": "43ER-053", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "multimètre"], "front": "Quelle borne du multimètre utilise-t-on **toujours** ?", "back": "La borne **COM**.", "createdAt": 1795015027484, "updatedAt": 1795015027484}'::jsonb),
('764543a9-f29e-4094-80c9-096eb4fa714f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "764543a9-f29e-4094-80c9-096eb4fa714f", "code": "43ER-054", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "multimètre"], "front": "Quel **calibre** choisir au début d''une mesure ?", "back": "Le **plus grand** calibre, puis on descend tant que la mesure reste possible.", "createdAt": 1795015027485, "updatedAt": 1795015027485}'::jsonb),
('e75c56b6-8267-4086-a8b2-c20918721089', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e75c56b6-8267-4086-a8b2-c20918721089", "code": "43ER-055", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "série"], "front": "Dans un circuit **en série**, comment est l''intensité ?", "back": "**La même partout** (unicité de l''intensité).", "createdAt": 1795015027486, "updatedAt": 1795015027486}'::jsonb),
('ee8957d1-383e-4c51-b488-047d0b3c666a', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "ee8957d1-383e-4c51-b488-047d0b3c666a", "code": "43ER-056", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "série", "idée fausse"], "front": "Le courant **s''use**-t-il en traversant une lampe ?", "back": "**Non** : l''intensité est la même avant et après la lampe.", "createdAt": 1795015027487, "updatedAt": 1795015027487}'::jsonb),
('076bed9b-0393-4ed0-bb8f-d776167efdf7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "076bed9b-0393-4ed0-bb8f-d776167efdf7", "code": "43ER-057", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "série", "calcul"], "front": "En série, $U_G = 6$ V et $U_1 = 2$ V. Combien vaut $U_2$ ?", "back": "$U_2 = U_G - U_1 = 6 - 2 = 4$ V.", "createdAt": 1795015027488, "updatedAt": 1795015027488}'::jsonb),
('22bdf39f-74e7-46ab-a57b-2ec7483978c0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "22bdf39f-74e7-46ab-a57b-2ec7483978c0", "code": "43ER-058", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "vocabulaire"], "front": "Quel est le **sens conventionnel** du courant ?", "back": "Le courant **sort par la borne +** du générateur et revient par la borne −.", "createdAt": 1795015027489, "updatedAt": 1795015027489}'::jsonb),
('aa95b2d1-65dc-4c6f-86fd-0505e68a7e5f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "aa95b2d1-65dc-4c6f-86fd-0505e68a7e5f", "code": "43ER-059", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "dérivation", "vocabulaire"], "front": "Qu''est-ce qu''un **nœud** dans un circuit ?", "back": "Un point où se rejoignent **au moins 3 fils**.", "createdAt": 1795015027490, "updatedAt": 1795015027490}'::jsonb),
('a50bc198-5690-44f4-953c-0adb8193faf7', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a50bc198-5690-44f4-953c-0adb8193faf7", "code": "43ER-060", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "dérivation"], "front": "Dans un circuit **avec dérivation**, comment se comporte l''intensité ?", "back": "Elle **se partage** entre les branches : $I = I_1 + I_2$.", "createdAt": 1795015027491, "updatedAt": 1795015027491}'::jsonb),
('053c66cc-6f01-47a7-b52f-63a40968529d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "053c66cc-6f01-47a7-b52f-63a40968529d", "code": "43ER-061", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "dérivation"], "front": "Dans un circuit **avec dérivation**, comment sont les tensions ?", "back": "**Égales** : $U_1 = U_2 = U_G$.", "createdAt": 1795015027492, "updatedAt": 1795015027492}'::jsonb),
('aff889f7-b75f-412f-8d56-18f41d7450a0', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "aff889f7-b75f-412f-8d56-18f41d7450a0", "code": "43ER-062", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "dérivation", "idée fausse"], "front": "Le générateur donne-t-il **toujours la même intensité** ?", "back": "**Non** : elle dépend du circuit. Ajouter une branche en dérivation fait augmenter l''intensité du générateur.", "createdAt": 1795015027493, "updatedAt": 1795015027493}'::jsonb),
('9e265c66-a2d6-46d4-a049-ec559166b2c4', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "9e265c66-a2d6-46d4-a049-ec559166b2c4", "code": "43ER-063", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "mesure"], "front": "On mesure 0,49 A au lieu de 0,50 A. La loi est-elle fausse ?", "back": "**Non** : c''est un **écart de mesure** (appareil, lecture, fils). Un petit écart ne contredit pas la loi.", "createdAt": 1795015027494, "updatedAt": 1795015027494}'::jsonb),
('a02a3851-fbb9-4397-b9dd-a9118b6dae8f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "a02a3851-fbb9-4397-b9dd-a9118b6dae8f", "code": "43ER-064", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "dérivation"], "front": "Comment sont branchées les lampes d''une maison ? Pourquoi ?", "back": "**En dérivation** : si une lampe grille, les autres restent allumées, et chacune a la même tension.", "createdAt": 1795015027495, "updatedAt": 1795015027495}'::jsonb),
('1883b1c8-4c40-46df-803c-671f4dd9859d', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "1883b1c8-4c40-46df-803c-671f4dd9859d", "code": "43ER-065", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "loi des nœuds"], "front": "Énonce la **loi des nœuds**.", "back": "**Ce qui arrive à un nœud en repart** : l''intensité qui entre est égale à la somme des intensités qui sortent.", "createdAt": 1795015027496, "updatedAt": 1795015027496}'::jsonb),
('d0988ecb-8aa9-46ec-b225-d9792406c978', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "d0988ecb-8aa9-46ec-b225-d9792406c978", "code": "43ER-066", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "loi des mailles"], "front": "Énonce la **loi des mailles**.", "back": "Dans une boucle fermée, la **tension du générateur se partage** entre les dipôles en série ; des dipôles en dérivation ont la même tension.", "createdAt": 1795015027497, "updatedAt": 1795015027497}'::jsonb),
('4ebedb3e-3c49-4cb6-828f-34c28262b8ea', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "4ebedb3e-3c49-4cb6-828f-34c28262b8ea", "code": "43ER-067", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "loi des nœuds", "4 lois"], "front": "De quelle loi découlent l''**unicité** et l''**additivité** de l''intensité ?", "back": "De la **loi des nœuds**.", "createdAt": 1795015027498, "updatedAt": 1795015027498}'::jsonb),
('e8ccbdb7-f303-4505-a6ca-f01406829c8f', '768856f9-b733-490b-9a10-701b0d8b3fd8', '{"id": "e8ccbdb7-f303-4505-a6ca-f01406829c8f", "code": "43ER-068", "origin": "ER", "subject": "Physique-Chimie", "level": "4e", "theme": "Énergie", "introUnitId": "e26c62b0-1f40-4637-8973-f51767cb35b1", "tags": ["4e", "Énergie", "Lois des circuits", "loi des mailles", "4 lois"], "front": "De quelle loi découlent l''**additivité** et l''**égalité** des tensions ?", "back": "De la **loi des mailles**.", "createdAt": 1795015027499, "updatedAt": 1795015027499}'::jsonb),
